import { LogicWrapper, MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { NodeKind } from '~/queries/schema/schema-general'

import { visionScannersEstimateCreate } from '../generated/api'
import type { EstimateResponseApi } from '../generated/api.schemas'
import { DEFAULT_MODEL } from './types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface watchPicksVolumeLogicValues {
    currentTeamId: number | null // teamLogic
    volumeEstimate: EstimateResponseApi | null
    volumeEstimateLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface watchPicksVolumeLogicActions {
    loadVolumeEstimate: (_: any) => any
    loadVolumeEstimateFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadVolumeEstimateSuccess: (
        volumeEstimate: EstimateResponseApi | null,
        payload?: any
    ) => {
        volumeEstimate: EstimateResponseApi | null
        payload?: any
    }
}

export type watchPicksVolumeLogicType = MakeLogicType<watchPicksVolumeLogicValues, watchPicksVolumeLogicActions>

export const watchPicksVolumeLogic: LogicWrapper<watchPicksVolumeLogicType> = kea<watchPicksVolumeLogicType>([
    path(['products', 'replay_vision', 'frontend', 'replay_scanners', 'watchPicksVolumeLogic']),

    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),

    loaders(({ values }) => ({
        volumeEstimate: [
            null as EstimateResponseApi | null,
            {
                loadVolumeEstimate: async (_, breakpoint) => {
                    if (!values.currentTeamId) {
                        return null
                    }
                    const estimate = await visionScannersEstimateCreate(String(values.currentTeamId), {
                        query: { kind: NodeKind.RecordingsQuery },
                        sampling_rate: 1,
                        model: DEFAULT_MODEL,
                    })
                    breakpoint()
                    return estimate
                },
            },
        ],
    })),

    afterMount(({ actions }) => {
        actions.loadVolumeEstimate()
    }),
])
